"""
Catálogo da ajuda nos campos: para cada campo de cada tela, o título, a explicação e o desenho do cartão que aparece
ao passar o mouse ou focar o campo (static/field_help.js).

Cada regra: p = expressão regular do início do caminho da tela; k = expressão regular (casamento inteiro) da chave do
campo — o `name`; sem name, "#" + id; "#check-all" / "#row-check" para as caixas de marcar das listas —; t = título;
d = explicação; g = "desenho:destaque" (as funções D.* do field_help.js). Vale a PRIMEIRA regra que casa: as telas
mais específicas vêm antes, e as regras gerais ("" = qualquer tela) ficam no fim.
tests/test_field_help.py confere que todo campo de toda tela tem regra e que todo desenho existe.
"""
from __future__ import annotations

import re

RULES: list[dict] = []
VERSION = "1"


def R(path: str, key: str, title: str, desc: str, g: str) -> None:
    RULES.append({"p": path, "k": key, "t": title, "d": desc, "g": g})


def find(path: str, key: str):
    for r in RULES:
        if re.match(f"(?:{r['p']})", path) and re.fullmatch(r["k"], key):
            return r
    return None


